    ring: "hover:shadow-glow-brand hover:border-brand-300",
    chip: "bg-brand-50 text-brand-700 border-brand-200",
    iconBadge: "from-brand-700 to-cyan-600",
    badgeShadow: "shadow-glow-brand",
    emoji: "🔵",
    typeLabel: "STANDARD",
    typeBadge: "bg-brand-50 text-brand-700 border-brand-200",
